import {curveViewModes} from './curve-view.js';
import {timelineFPS,timelineSnap} from './timeline-rate.js';
import {sequenceKeyLimits} from './sequence-key-storage.js';
import {TimelineEditor} from './timeline-editor.js';
import {sequenceCurveType} from './sequence-curves.js';
import {validGameplayAsset} from './gameplay-assets.js';
// Adapt the existing key/handle editor; sequence bindings and playback settings
// never become editable Timeline tracks or a second persisted asset.
export function sequenceCurveEditor(element,controller,track){
 const data=controller.doc.data,available=data.tracks.filter(t=>sequenceCurveType(t)&&!t.quaternionInterpolation),view=controller.doc.view??={},ids=new Set((view.sequenceCurveTracks||[track.id]).filter(id=>available.some(t=>t.id===id)));ids.add(track.id);view.sequenceCurveTracks=[...ids];
 const node={id:'sequence_'+track.id,timeline:{length:data.length,playRate:data.rate,loop:data.loop,autoplay:false,lastKeyframe:false,ignoreTimeDilation:false,tracks:available.filter(t=>ids.has(t.id)).map(t=>({id:t.id,name:t.name,type:sequenceCurveType(t),interpolation:'linear',preInfinity:t.preInfinity,postInfinity:t.postInfinity,infinityDomain:structuredClone(t.infinityDomain),keys:structuredClone(t.keys)}))}};
 const apply=(candidate,next)=>{if(candidate.tracks.length!==ids.size||new Set(candidate.tracks.map(t=>t.id)).size!==ids.size)return false;for(const source of candidate.tracks){const destination=next.tracks.find(t=>t.id===source.id);if(!ids.has(source.id)||!destination||destination.quaternionInterpolation||sequenceCurveType(destination)!==source.type)return false;destination.keys=structuredClone(source.keys);for(const p of ['preInfinity','postInfinity','infinityDomain'])if(source[p]===undefined)delete destination[p];else destination[p]=structuredClone(source[p]);}return true;};
 element.dataset.sequenceCurve='true';
 element.dataset.sequenceMulti=String(ids.size>1);
 const editor=new TimelineEditor(element,()=>node,{
  multiTrack:true,toolState:view.sequenceCurveTools??={options:{},open:false},hiddenChannels:view.sequenceCurveHidden||[],hiddenChannelsChanged:value=>{view.sequenceCurveHidden=value;},viewMode:()=>view.sequenceCurveView||'absolute',maxKeys:sequenceKeyLimits.perTrack,bakeFPS:()=>timelineFPS(controller.doc.data),snapTime:time=>timelineSnap(controller.doc.data,time),enabled:()=>!controller.hooks.running?.(),toolsEditable:true,eulerAngles:track.type==='rotation',
  activeTrack:id=>{controller.selection=controller.curveTrack=id;editor.hooks.eulerAngles=controller.doc.data.tracks.find(t=>t.id===id)?.type==='rotation';const select=editor.el.querySelector('[data-sequence-curve-track]');if(select)select.value=id;for(const button of editor.el.querySelectorAll('[data-track]'))button.closest('.curve-track').classList.toggle('selected',button.dataset.track===id);},
  toolAllowed:(operation,id)=>operation!=='eulerFilter'||controller.doc.data.tracks.find(t=>t.id===id)?.type==='rotation',
  rangeEditable:!track.quaternionInterpolation,
  rendered:editor=>{for(const button of editor.el.querySelectorAll('[data-track]')){const row=node.timeline.tracks.find(t=>t.id===button.dataset.track);button.title=row.name+' · '+row.keys.length+' keys';}const bar=editor.el.querySelector('.curve-keybar'),label=editor.document.createElement('label'),select=editor.document.createElement('select');label.append('곡선');select.dataset.sequenceCurveTrack='';select.setAttribute('aria-label','활성 곡선');select.style.width='140px';for(const row of available){const option=editor.document.createElement('option');option.value=row.id;option.textContent=row.name;select.append(option);}select.value=editor.trackId;select.onchange=()=>{const chosen=available.find(t=>t.id===select.value);if(!chosen)return;controller.selection=controller.curveTrack=chosen.id;view.sequenceCurveTracks=ids.size===1?[chosen.id]:[...new Set([...ids,chosen.id])];controller.render();controller.element.querySelector('[data-sequence-curve-track]')?.focus();};label.append(select);bar.prepend(label);
   const picker=editor.document.createElement('details'),summary=editor.document.createElement('summary');picker.className='sequence-curve-picker';summary.textContent='함께 편집 · '+ids.size;picker.append(summary);for(const row of available){const item=editor.document.createElement('label'),input=editor.document.createElement('input');input.type='checkbox';input.dataset.sequenceCurveVisible=row.id;input.checked=ids.has(row.id);input.disabled=ids.size===1&&input.checked;input.onchange=()=>{input.checked?ids.add(row.id):ids.delete(row.id);view.sequenceCurveTracks=[...ids];if(!ids.has(controller.curveTrack))controller.selection=controller.curveTrack=ids.values().next().value;controller.render();const current=controller.element.querySelector('.sequence-curve-picker');if(current)current.open=true;};item.append(input,editor.document.createTextNode(row.name));picker.append(item);}label.after(picker);const mode=editor.document.createElement('select');mode.dataset.sequenceCurveView='';mode.setAttribute('aria-label','곡선 보기');for(const value of curveViewModes){const option=editor.document.createElement('option');option.value=value;option.textContent={absolute:'실제 값',normalized:'정규화',stacked:'쌓기'}[value];mode.append(option);}mode.value=view.sequenceCurveView||'absolute';mode.onchange=()=>{view.sequenceCurveView=mode.value;editor.fit();editor.draw();editor.el.querySelector('.curve-plot').scrollTop=0;};picker.after(mode);const channels=editor.el.querySelector('[data-channel-track="'+editor.trackId+'"]')?.closest('.curve-channels');if(channels&&ids.size===1)picker.after(channels);editor.el.querySelector('.curve-footer').prepend(editor.el.querySelector('[data-fit]'));editor.readableLabels();},
  before:()=>controller.hooks.before(),error:message=>controller.hooks.error(message),
  validate:candidate=>{if(controller.hooks.running?.())return false;const next={...controller.doc.data,tracks:controller.doc.data.tracks.map(t=>ids.has(t.id)?{...t}:t)};return apply(candidate,next)&&validGameplayAsset('sequenceasset',next);},
  change:()=>{apply(node.timeline,controller.doc.data);controller.hooks.change();controller.visualPreview?.sample(controller.time);},
  sample:time=>{controller.time=time;controller.visualPreview?.sample(time);controller.timelineTime();}
 });
 editor.trackId=track.id;editor.time=controller.time;editor.fit();editor.render();return editor;
}
